class Solution {
public:
    int numSubarraysWithSum(vector<int>& nums, int goal) {
        map<int, int> seen;
        seen[0] = 1;
        int sum = 0, count = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            sum += nums[i];
            int need = sum - goal;
            if (seen.count(need)) count += seen[need];
            seen[sum]++;
        }
        return count;
    }
};
